const toggle=document.createElement('button');toggle.className='duel-toggle';toggle.id='duelToggle';toggle.textContent='CPU';toggle.title='Alternar CPU / dois jogadores';$('.battle-top').appendChild(toggle);toggle.addEventListener('click',()=>{twoPlayer=!twoPlayer;toggle.textContent=twoPlayer?'2P LOCAL':'CPU';toggle.classList.toggle('active',twoPlayer);$('#battleHint').textContent=twoPlayer?'P1 WASD + J/K/L · P2 setas + numpad':'Acumule Heat e encontre sua abertura.';p2.block=false});

